/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var customEncodingProperty = require( './custom' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getEnter = require( './enter/get.js' );
var setEnter = require( './enter/set.js' );
var getExit = require( './exit/get.js' );
var setExit = require( './exit/set.js' );

var getHover = require( './hover/get.js' );
var setHover = require( './hover/set.js' );

var getProperties = require( './properties/get.js' );

var getUpdate = require( './update/get.js' );
var setUpdate = require( './update/set.js' );


// VARIABLES //

var debug = logger( 'vega:mark:encoding:main' );
var KNOWN_SETS = [
	'enter',
	'exit',
	'hover',
	'update'
];
var isKnownSet = contains( KNOWN_SETS );


// MAIN //

/**
* Mark encoding constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {EncodingSet} [options.enter] - encoding set specifying visual properties when marks are newly added to a visualization scene
* @param {EncodingSet} [options.exit] - encoding set specifying visual properties when marks are removed from a visualization scene
* @param {EncodingSet} [options.hover] - encoding set specifying visual properties when the mouse cursor hovers over a mark instance
* @param {EncodingSet} [options.update] - encoding set specifying visual properties when a visualization scene updates
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Encoding} encoding instance
*
* @example
* var encoding = new Encoding();
* // returns <Encoding>
*/
function Encoding( options ) {
	var nargs;
	var keys;
	var v;
	var k;
	var o;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Encoding ) ) {
		if ( nargs === 0 ) {
			return new Encoding();
		}
		return new Encoding( options );
	}
	EventEmitter.call( this );
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	setNonEnumerableReadOnly( this, '_properties', properties.slice() );

	// Check for custom encoding set names...
	keys = objectKeys( options );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		if ( isKnownSet( k ) ) {
			continue;
		}
		// Consider any unknown property to be a custom encoding set:
		v = options[ k ];

		// Define a read-write accessor specific to this instance for handling the custom encoding set:
		o = customEncodingProperty( k );
		setReadWriteAccessor( this, k, o.get( k ), o.set( k ) );

		// Assign the option value to the corresponding field:
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
		// Add the property name to the encoding's list of property to ensure proper JSON serialization:
		this._properties.push( k );
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Encoding, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Encoding
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Encoding, 'name', 'Encoding' );

/**
* Encoding specifying visual encoding properties when marks are newly added to a visualization scene.
*
* @name enter
* @memberof Encoding.prototype
* @type {(EncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
*
* var encodingSet = new EncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new Encoding({
*     'enter': encodingSet
* });
*
* var v = encoding.enter;
* // returns <EncodingSet>
*/
setReadWriteAccessor( Encoding.prototype, 'enter', getEnter, setEnter );

/**
* Encoding specifying visual encoding properties when marks are removed from a visualization scene.
*
* @name exit
* @memberof Encoding.prototype
* @type {(EncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
*
* var encodingSet = new EncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new Encoding({
*     'exit': encodingSet
* });
*
* var v = encoding.exit;
* // returns <EncodingSet>
*/
setReadWriteAccessor( Encoding.prototype, 'exit', getExit, setExit );

/**
* Encoding specifying visual encoding properties when the mouse cursor hovers over a mark instance.
*
* @name hover
* @memberof Encoding.prototype
* @type {(EncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
*
* var encodingSet = new EncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new Encoding({
*     'hover': encodingSet
* });
*
* var v = encoding.hover;
* // returns <EncodingSet>
*/
setReadWriteAccessor( Encoding.prototype, 'hover', getHover, setHover );

/**
* Encoding properties.
*
* @name properties
* @memberof Encoding.prototype
* @type {Array<string>}
*
* @example
* var encoding = new Encoding();
*
* var v = encoding.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Encoding.prototype, 'properties', getProperties );

/**
* Encoding specifying visual encoding properties when a visualization scene updates.
*
* @name update
* @memberof Encoding.prototype
* @type {(EncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
*
* var encodingSet = new EncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new Encoding({
*     'update': encodingSet
* });
*
* var v = encoding.update;
* // returns <EncodingSet>
*/
setReadWriteAccessor( Encoding.prototype, 'update', getUpdate, setUpdate );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Encoding.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var encoding = new Encoding();
*
* var v = encoding.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Encoding.prototype, 'toJSON', function toJSON() {
	return instance2json( this, this._properties );
});


// EXPORTS //

module.exports = Encoding;
